INSERT INTO "followups" VALUES(3,'gate1_baseline_2026-09-25',1,'Which PSP dollar figures can be stated explicitly?','~$115K active pipeline; deal count only for closed business (no closed-revenue figure)','pipeline-management',NULL,'2026-09-25 18:02:44','2026-09-25 18:02:44',NULL,NULL,NULL,NULL);
