INSERT INTO "generated_resumes" VALUES(4,NULL,'v2','{"version": "v2", "generated_at": "2026-09-25T14:04:25", "jd": null, "identity": {"name": "Tim King", "formal_name": "Timothy King", "location": "New York, NY", "phone": "(617) 960-7176", "email": "tim.r.king11@gmail.com", "linkedin": "linkedin.com/in/timothy-king1124", "headline_default": "GO-TO-MARKET STRATEGY \u00b7 ENTERPRISE & MEDIA SALES \u00b7 AI-ENABLED REVENUE", "linkedin_headline": "Sales Professional | Marketing, Advertising, Product, Services, & Sales GTM Strategist Providing Advisory Services | Systems Thinker | Process Engineer | AI Adoption Enthusiast"}, "headline": "GO-TO-MARKET STRATEGY \u00b7 ENTERPRISE & MEDIA SALES \u00b7 AI-ENABLED REVENUE", "summary": "Revenue and go-to-market operator with eight years of full-cycle B2B, media, and enterprise technology sales, currently advising the CEO and board of an AI start-up on go-to-market, pricing, and buy-vs-build strategy. Wins net-new business from cold \u2014 Fortune 500 accounts at TEKsystems, NFL and MLB team partnerships at Professional Sports Publications \u2014 by qualifying on the budget that can actually fund a buy and building the CPM, CPA, and unit-economics case a client''s finance team can defend. Has led a team of up to five, coaching performance against daily process and 1:1 metrics, and uses Claude and OpenAI models daily to compress research, account mapping, and proposal cycles.", "competencies": ["Go-To-Market Strategy", "New Business Development", "Full-Cycle Enterprise Sales (Prospect to Close)", "Consultative & Diagnostic Discovery", "Contract & Proposal Development", "Complex Multi-Stakeholder Negotiation", "Revenue Forecasting & KPI Management", "Funding-Source Diagnostics (Co-Op, MDF, Sponsorship, 501(c)(3))", "CPM, CPA & ROI Business Cases", "Buy-vs-Build & Competitive Analysis", "Sales Team Coaching & Performance Management", "Prompt Engineering & AI-Enabled Workflow"], "technologies": ["Salesforce", "LinkedIn Sales Navigat